def is_valid_percentage_string(s):
    if not s.endswith('%'):
        return False
    number_part = s[:-1]
    if len(number_part) == 0:
        return False
    if number_part[0] == '.' or number_part[-1] == '.':
        return False
    dot_seen = False
    for ch in number_part:
        if ch == '.':
            if dot_seen:
                return False
            dot_seen = True
        elif not ch.isdigit():
            return False
    value = float(number_part)
    return 0 <= value <= 100

