def distinct_prime_factors(n):
    n = abs(n)
    def helper(m, d, acc):
        if d * d > m:
            if m > 1:
                acc.append(m)
            return acc
        if m % d == 0:
            acc.append(d)
            while m % d == 0:
                m //= d
            return helper(m, d + 1, acc)
        return helper(m, d + 1, acc)
    return helper(n, 2, [])

